package br.com.onda;
import android.media.*;import android.os.SystemClock;import java.io.*;import java.nio.*;
/** Reuse AAC when present; otherwise decode and encode a mono/stereo AAC soundtrack on demand. */
final class PhotoAudio {
 static void prepare(File source,File output,DownloadMux.Cancel cancel)throws IOException{
  MediaExtractor extractor=new MediaExtractor();MediaCodec decoder=null,encoder=null;PhotoCodecOutput sink=null;
  try{extractor.setDataSource(source.getPath());int track=AudioTracks.select(extractor);MediaFormat input=extractor.getTrackFormat(track);if(AudioTracks.aac(input)){DownloadMux.extract(MediaInput.file(source),output,cancel);return;}extractor.selectTrack(track);sink=new PhotoCodecOutput(output);
   if("audio/raw".equals(input.getString(MediaFormat.KEY_MIME))){int rate=input.getInteger(MediaFormat.KEY_SAMPLE_RATE),channels=input.getInteger(MediaFormat.KEY_CHANNEL_COUNT);encoder=encoder(rate,channels);ByteBuffer raw=ByteBuffer.allocate(65536);long frames=0;while(true){cancel.check();raw.clear();int size=extractor.readSampleData(raw,0);if(size<0)break;if((extractor.getSampleFlags()&MediaExtractor.SAMPLE_FLAG_ENCRYPTED)!=0)throw new IOException("Áudio protegido não é convertido");raw.position(0);raw.limit(size);frames=feed(encoder,sink,raw,rate,channels,frames,cancel);extractor.advance();}end(encoder,sink,rate,frames,cancel);sink.finish();return;}
   input.setInteger(MediaFormat.KEY_PCM_ENCODING,AudioFormat.ENCODING_PCM_16BIT);decoder=MediaCodec.createDecoderByType(input.getString(MediaFormat.KEY_MIME));decoder.configure(input,null,null,0);decoder.start();boolean inEnd=false,outEnd=false;int rate=0,channels=0;long frames=0,last=SystemClock.elapsedRealtime();MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();
   while(!outEnd){cancel.check();if(SystemClock.elapsedRealtime()-last>30000)throw new IOException("O codec de áudio parou de responder");if(!inEnd){int index=decoder.dequeueInputBuffer(10000);if(index>=0){ByteBuffer data=decoder.getInputBuffer(index);if(data==null)throw new IOException("Entrada de áudio indisponível");data.clear();int size=extractor.readSampleData(data,0);if(size<0){decoder.queueInputBuffer(index,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inEnd=true;}else{if((extractor.getSampleFlags()&MediaExtractor.SAMPLE_FLAG_ENCRYPTED)!=0)throw new IOException("Áudio protegido não é convertido");decoder.queueInputBuffer(index,0,size,Math.max(0,extractor.getSampleTime()),0);extractor.advance();}last=SystemClock.elapsedRealtime();}}
    int index=decoder.dequeueOutputBuffer(info,10000);if(index==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){if(encoder!=null)throw new IOException("Formato de áudio variável não suportado");MediaFormat format=decoder.getOutputFormat();rate=format.getInteger(MediaFormat.KEY_SAMPLE_RATE);channels=format.getInteger(MediaFormat.KEY_CHANNEL_COUNT);if(format.containsKey(MediaFormat.KEY_PCM_ENCODING)&&format.getInteger(MediaFormat.KEY_PCM_ENCODING)!=AudioFormat.ENCODING_PCM_16BIT)throw new IOException("PCM de 16 bits necessário");encoder=encoder(rate,channels);last=SystemClock.elapsedRealtime();}else if(index>=0){try{if(info.size>0){if(encoder==null)throw new IOException("Formato de áudio não informado");ByteBuffer pcm=decoder.getOutputBuffer(index);if(pcm==null)throw new IOException("Áudio decodificado indisponível");pcm.position(info.offset);pcm.limit(info.offset+info.size);frames=feed(encoder,sink,pcm,rate,channels,frames,cancel);}outEnd=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;last=SystemClock.elapsedRealtime();}finally{decoder.releaseOutputBuffer(index,false);}}if(encoder!=null&&sink.drain(encoder,cancel))last=SystemClock.elapsedRealtime();
   }
   if(encoder==null||frames==0)throw new IOException("Nenhum áudio foi encontrado");end(encoder,sink,rate,frames,cancel);sink.finish();
  }catch(RuntimeException e){throw new IOException("Não foi possível preparar o áudio AAC neste aparelho",e);}finally{PhotoCodecOutput.release(decoder);PhotoCodecOutput.release(encoder);if(sink!=null)sink.close();extractor.release();}
 }
 static MediaCodec encoder(int rate,int channels)throws IOException{if(channels<1||channels>2||rate<8000||rate>96000)throw new IOException("É necessário áudio mono ou estéreo compatível com AAC");MediaFormat f=MediaFormat.createAudioFormat("audio/mp4a-latm",rate,channels);f.setInteger(MediaFormat.KEY_AAC_PROFILE,MediaCodecInfo.CodecProfileLevel.AACObjectLC);f.setInteger(MediaFormat.KEY_BIT_RATE,channels==1?128000:192000);f.setInteger(MediaFormat.KEY_MAX_INPUT_SIZE,32768);MediaCodec codec=MediaCodec.createEncoderByType("audio/mp4a-latm");try{codec.configure(f,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);codec.start();return codec;}catch(RuntimeException e){PhotoCodecOutput.release(codec);throw e;}}
 static long feed(MediaCodec codec,PhotoCodecOutput sink,ByteBuffer pcm,int rate,int channels,long frames,DownloadMux.Cancel cancel)throws IOException{int frameBytes=channels*2;if(pcm.remaining()%frameBytes!=0)throw new IOException("Bloco PCM inválido");long last=SystemClock.elapsedRealtime();while(pcm.hasRemaining()){cancel.check();if(SystemClock.elapsedRealtime()-last>30000)throw new IOException("O codificador AAC parou de responder");int index=codec.dequeueInputBuffer(10000);if(index>=0){ByteBuffer input=codec.getInputBuffer(index);if(input==null)throw new IOException("Entrada AAC indisponível");input.clear();int count=Math.min(input.remaining(),pcm.remaining())/frameBytes*frameBytes;if(count==0)throw new IOException("Bloco AAC pequeno demais");int limit=pcm.limit();pcm.limit(pcm.position()+count);input.put(pcm);pcm.limit(limit);codec.queueInputBuffer(index,0,count,frames*1000000L/rate,0);frames+=count/frameBytes;last=SystemClock.elapsedRealtime();}if(sink.drain(codec,cancel))last=SystemClock.elapsedRealtime();}return frames;}
 static void end(MediaCodec codec,PhotoCodecOutput sink,int rate,long frames,DownloadMux.Cancel cancel)throws IOException{boolean queued=false;long last=SystemClock.elapsedRealtime();while(!sink.ended){cancel.check();if(SystemClock.elapsedRealtime()-last>30000)throw new IOException("O codificador AAC não concluiu");if(!queued){int index=codec.dequeueInputBuffer(10000);if(index>=0){codec.queueInputBuffer(index,0,0,frames*1000000L/rate,MediaCodec.BUFFER_FLAG_END_OF_STREAM);queued=true;last=SystemClock.elapsedRealtime();}}if(sink.drain(codec,cancel))last=SystemClock.elapsedRealtime();}}
}
